export async function getSpectrumRow(): Promise<any> {
  const row = Array.from({ length: 512 }, (_, i) => 0.1 + 0.05 * Math.random() + ((i > 190 && i < 194) || (i > 300 && i < 303) ? 0.6 : 0))
  return { row, loHz: 0, hiHz: 4000, source: 'audio' }
}
